mod solution;

fn main() {
    let cases = [
    (r#"[4,2,6,1,3,5,7]"#, r#"1,2,3,4,5,6,7"#),
    (r#"[2,1,3]"#, r#"1,2,3"#),
    (r#"
[2,1,3]
"#, r#"1,2,3"#),
    (r#"  
[4,2,6,1,3,5,7]
  "#, r#"1,2,3,4,5,6,7"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS tree-inorder");
}
